CREATE OR REPLACE FUNCTION public.protect_profile_security_fields() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$BEGIN IF NOT public.is_admin() AND (NEW.is_approved IS DISTINCT FROM OLD.is_approved OR NEW.approved_by IS DISTINCT FROM OLD.approved_by OR NEW.approved_at IS DISTINCT FROM OLD.approved_at OR NEW.is_blocked IS DISTINCT FROM OLD.is_blocked OR NEW.block_reason IS DISTINCT FROM OLD.block_reason OR NEW.risk_score IS DISTINCT FROM OLD.risk_score OR NEW.risk_level IS DISTINCT FROM OLD.risk_level OR NEW.auto_unlock_at IS DISTINCT FROM OLD.auto_unlock_at) THEN RAISE EXCEPTION 'Security fields may only be changed by administrators';END IF;RETURN NEW;END$$;
CREATE TRIGGER protect_profile_security BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_profile_security_fields();REVOKE ALL ON FUNCTION public.protect_profile_security_fields() FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.protect_profile_security_fields() TO service_role;
CREATE OR REPLACE FUNCTION public.delete_bid_safe(p_bid_id uuid,p_reason text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$DECLARE lid uuid;BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Forbidden';END IF;SELECT lot_id INTO lid FROM public.bids WHERE id=p_bid_id;DELETE FROM public.bids WHERE id=p_bid_id;UPDATE public.lots l SET current_price=COALESCE((SELECT max(amount) FROM public.bids WHERE lot_id=lid),l.starting_price),bids_count=(SELECT count(*) FROM public.bids WHERE lot_id=lid),winner_id=(SELECT user_id FROM public.bids WHERE lot_id=lid ORDER BY amount DESC,created_at LIMIT 1) WHERE id=lid;RETURN jsonb_build_object('success',true,'reason',p_reason);END$$;
CREATE OR REPLACE FUNCTION public.revert_sold_lot(p_lot_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Forbidden';END IF;UPDATE public.lots SET status='upcoming',winner_id=NULL,winner_link_reason=NULL,is_currently_live=false WHERE id=p_lot_id;RETURN jsonb_build_object('success',true);END$$;
GRANT EXECUTE ON FUNCTION public.delete_bid_safe(uuid,text) TO authenticated;GRANT EXECUTE ON FUNCTION public.revert_sold_lot(uuid) TO authenticated;